package main

import "fmt"

type ValidationError struct {
	Field string
}

func (e *ValidationError) Error() string {
	return fmt.Sprintf("字段 %s 不合法", e.Field)
}

func load(id int) error {
	if id <= 0 {
		return fmt.Errorf("加载用户: id 必须为正数")
	}
	if id == 3 {
		panic("底层连接炸了")
	}
	if id != 1 {
		return &ValidationError{Field: "id"}
	}
	return nil
}

func handle(id int) (err error) {
	defer func() {
		if r := recover(); r != nil {
			err = fmt.Errorf("处理用户 %d 时 panic: %v", id, r)
		}
	}()
	return load(id)
}

func main() {
	for _, id := range []int{0, 2, 3, 1} {
		err := handle(id)
		if err == nil {
			continue
		}
		fmt.Println("记录一次:", err) // 只在最外层记录
		if ve, ok := err.(*ValidationError); ok {
			fmt.Println("校验字段:", ve.Field)
		}
	}
}
